import { SlashCommandBuilder, AttachmentBuilder } from 'discord.js';
import { InteractionHelper } from '../../utils/interactionHelper.js';
import { logger } from '../../utils/logger.js';
import { checkRateLimit } from '../../utils/rateLimiter.js';
import { getPrefixText, plainReply, syntaxReply } from '../../utils/punishmentTools.js';
import { createCanvas, loadImage, GlobalFonts } from '@napi-rs/canvas';

// ==========================================
// .quote  -  turns a message into a quote picture
//
//   Reply to a message and type   .quote          (quotes that message)
//   .quote meow                                   (quotes your own text)
// ==========================================

const RATE_LIMIT_ATTEMPTS = 5;
const RATE_LIMIT_WINDOW_MS = 20000;
const AVATAR_OPTIONS = { extension: 'png', size: 1024, forceStatic: true };

export default {
    data: new SlashCommandBuilder()
        .setName('quote')
        .setDescription('Make a quote picture (reply to a message with .quote, or .quote <text>)')
        .addStringOption((option) =>
            option
                .setName('text')
                .setDescription('What to quote (leave empty and reply to a message with .quote instead)')
                .setRequired(false),
        ),
    category: 'Fun',

    // Slash command: /quote text:meow
    async execute(interaction, config, client) {
        const text = (interaction.options.getString('text') || '').trim();

        if (!text) {
            return plainReply(interaction, 'Nothing to quote. Use /quote text:something');
        }

        await InteractionHelper.safeDefer(interaction);

        const member = interaction.member ?? null;

        return sendQuote(interaction, {
            text,
            user: interaction.user,
            member,
            replyTo: null,
        });
    },

    // Prefix command: .quote   (as a reply)   or   .quote <text>
    async prefixExecute(interaction, config, client) {
        const original = interaction.message ?? interaction._responseCoordinator?.message ?? null;
        const typed = getPrefixText(interaction, 'quote');

        // Reply to a message  ->  quote that message (only when no text was typed)
        if (!typed && original?.reference?.messageId) {
            const target = await original.fetchReference().catch(() => null);

            if (!target) {
                return plainReply(interaction, "Couldn't find the message you replied to");
            }

            const text = getMessageText(target);

            if (!text) {
                return plainReply(interaction, 'Nothing to quote in that message');
            }

            const member = target.member ?? (await fetchMember(target)) ?? null;

            return sendQuote(interaction, {
                text,
                user: target.author,
                member,
                replyTo: original,
            });
        }

        // .quote <text>  ->  quote what was typed, as the person who typed it
        if (typed) {
            // cleanContent turns <@123> into @name, so mentions look normal in the picture
            const clean = original?.cleanContent
                ? original.cleanContent.replace(/^\S*?quote(?:\s+|$)/i, '').trim()
                : typed;

            return sendQuote(interaction, {
                text: clean || typed,
                user: original.author,
                member: original.member ?? null,
                replyTo: original,
            });
        }

        return syntaxReply(interaction, 'quote');
    },
};

// The text of a message. Mentions are written out as names, custom emojis stay as <:name:id>.
function getMessageText(message) {
    const text = (message.cleanContent || '').trim();

    if (text) return text;

    // Bot messages often only have an embed
    const embed = message.embeds?.find((item) => item.description);

    return embed ? embed.description.trim() : '';
}

async function fetchMember(message) {
    if (!message.guild || !message.author || message.webhookId) return null;

    return message.guild.members.fetch(message.author.id).catch(() => null);
}

async function sendQuote(interaction, { text, user, member, replyTo }) {
    const rateLimitKey = `quote:${interaction.user.id}`;

    if (!(await checkRateLimit(rateLimitKey, RATE_LIMIT_ATTEMPTS, RATE_LIMIT_WINDOW_MS))) {
        return plainReply(interaction, 'Slow down, try again in a few seconds');
    }

    try {
        await interaction.channel?.sendTyping?.().catch(() => {});

        const buffer = await renderQuoteImage({
            text,
            name: member?.displayName ?? user.globalName ?? user.username,
            handle: user.username,
            avatarUrl: (member ?? user).displayAvatarURL(AVATAR_OPTIONS),
        });

        const payload = {
            files: [new AttachmentBuilder(buffer, { name: 'quote.png' })],
            allowedMentions: { parse: [], repliedUser: false },
        };

        // Prefix commands answer the command message, like a normal reply
        if (replyTo && interaction._isPrefixCommand) {
            payload.reply = { messageReference: replyTo.id, failIfNotExists: false };
        }

        await InteractionHelper.universalReply(interaction, payload);

        logger.debug('Quote command executed', {
            userId: interaction.user.id,
            quotedUserId: user.id,
            guildId: interaction.guildId,
        });
    } catch (error) {
        logger.error('Quote command failed:', error);

        return plainReply(interaction, "Couldn't make the quote");
    }
}


// ==========================================
// PICTURE MAKER (fonts are inside this file, nothing else to upload)
// ==========================================

// ==========================================
// QUOTE IMAGE
//
//   [ avatar fading into black ]   quote text (centered)
//                                  - name
//                                  @username
//
// Custom Discord emojis and normal emojis are drawn inside the text as pictures.
// ==========================================


// Fonts (Poppins, embedded)
const FONT_QUOTETEXT = '';
const FONT_QUOTENAME = '';
const FONT_QUOTEHANDLE = '';

GlobalFonts.register(Buffer.from(FONT_QUOTETEXT, 'base64'), 'QuoteText');
GlobalFonts.register(Buffer.from(FONT_QUOTENAME, 'base64'), 'QuoteName');
GlobalFonts.register(Buffer.from(FONT_QUOTEHANDLE, 'base64'), 'QuoteHandle');

const TEXT_FONT = 'QuoteText, sans-serif';
const NAME_FONT = 'QuoteName, sans-serif';
const HANDLE_FONT = 'QuoteHandle, sans-serif';

// ---------- look & size (change these to restyle the image) ----------
const WIDTH = 1140;
const HEIGHT = 600;
const AVATAR_WIDTH = 506;          // how much of the left side the avatar uses
const AVATAR_FADE_START = 0.55;    // the avatar starts fading into black here (0 - 1 of its width)
const CORNER_RADIUS = 36;
const TEXT_PADDING = 52;           // space left/right of the text
const QUOTE_FONT_MAX = 54;
const QUOTE_FONT_MIN = 22;
const NAME_FONT_SIZE = 28;
const HANDLE_FONT_SIZE = 16;
const LINE_HEIGHT = 1.32;
const MAX_QUOTE_CHARS = 450;
const FETCH_TIMEOUT_MS = 6000;

// ---------- emoji handling ----------
const EMOJI_REGEX = new RegExp(
    [
        '<a?:\\w{2,32}:\\d{15,25}>',                                                  // custom Discord emoji
        '\\p{Regional_Indicator}{2}',                                                 // flags
        '[#*0-9]\\uFE0F?\\u20E3',                                                      // keycaps
        '\\p{Extended_Pictographic}(?:\\uFE0F|[\\u{1F3FB}-\\u{1F3FF}])*' +
            '(?:\\u200D\\p{Extended_Pictographic}(?:\\uFE0F|[\\u{1F3FB}-\\u{1F3FF}])*)*', // normal emoji (+ skin tones, joined emoji)
    ].join('|'),
    'gu',
);

const CUSTOM_EMOJI = /^<(a?):\w{2,32}:(\d{15,25})>$/;
const TWEMOJI_BASE = 'https://cdn.jsdelivr.net/gh/jdecked/twemoji@15.1.0/assets/72x72/';
const imageCache = new Map();
const IMAGE_CACHE_LIMIT = 300;

function emojiUrl(emoji) {
    const custom = emoji.match(CUSTOM_EMOJI);

    if (custom) {
        return `https://cdn.discordapp.com/emojis/${custom[2]}.png?size=96`;
    }

    // Same file naming as Twemoji: code points joined with "-", FE0F removed unless it is a joined emoji
    let chars = [...emoji];
    if (!emoji.includes('\u200D')) {
        chars = chars.filter((char) => char !== '\uFE0F');
    }

    return `${TWEMOJI_BASE}${chars.map((char) => char.codePointAt(0).toString(16)).join('-')}.png`;
}

async function fetchImage(url) {
    if (imageCache.has(url)) {
        return imageCache.get(url);
    }

    let image = null;

    try {
        const response = await fetch(url, { signal: AbortSignal.timeout(FETCH_TIMEOUT_MS) });

        if (response.ok) {
            image = await loadImage(Buffer.from(await response.arrayBuffer()));
        }
    } catch (error) {
        logger.debug(`Quote image: could not load ${url}: ${error.message}`);
    }

    if (imageCache.size >= IMAGE_CACHE_LIMIT) {
        imageCache.delete(imageCache.keys().next().value);
    }
    imageCache.set(url, image);

    return image;
}

// Fancy "𝓦𝓲𝓽𝓬𝓱" style letters are not in the font, so turn them into normal letters
function normalizeFancyLetters(text) {
    return text.replace(/[\u{1D400}-\u{1D7FF}]+/gu, (chunk) => chunk.normalize('NFKC'));
}

// Splits text into  { type: 'text' | 'emoji' | 'newline' }  pieces
function tokenize(text) {
    const tokens = [];
    let last = 0;

    for (const match of text.matchAll(EMOJI_REGEX)) {
        if (match.index > last) {
            tokens.push({ type: 'text', value: text.slice(last, match.index) });
        }
        tokens.push({ type: 'emoji', value: match[0], image: null });
        last = match.index + match[0].length;
    }

    if (last < text.length) {
        tokens.push({ type: 'text', value: text.slice(last) });
    }

    // Break the text pieces into words, spaces and new lines
    const atoms = [];

    for (const token of tokens) {
        if (token.type === 'emoji') {
            atoms.push(token);
            continue;
        }

        for (const part of token.value.split(/(\n|[ \t]+)/)) {
            if (part === '') continue;
            if (part === '\n') atoms.push({ type: 'newline' });
            else if (/^[ \t]+$/.test(part)) atoms.push({ type: 'space' });
            else atoms.push({ type: 'word', value: part });
        }
    }

    return atoms;
}

// Downloads every emoji picture first. Ones that fail are drawn as normal text instead.
async function loadEmojis(atoms) {
    await Promise.all(
        atoms
            .filter((atom) => atom.type === 'emoji')
            .map(async (atom) => {
                atom.image = await fetchImage(emojiUrl(atom.value));

                if (!atom.image) {
                    atom.type = CUSTOM_EMOJI.test(atom.value) ? 'skip' : 'word';
                }
            }),
    );

    return atoms.filter((atom) => atom.type !== 'skip');
}

function measureAtom(ctx, atom, fontSize) {
    if (atom.type === 'space') return ctx.measureText(' ').width;
    if (atom.type === 'emoji') return fontSize * 1.08;
    if (atom.type === 'word') return ctx.measureText(atom.value).width;
    return 0;
}

// Cuts a word that is wider than a whole line into pieces
function splitLongWord(ctx, word, maxWidth) {
    const pieces = [];
    let current = '';

    for (const char of word) {
        if (current && ctx.measureText(current + char).width > maxWidth) {
            pieces.push(current);
            current = '';
        }
        current += char;
    }

    if (current) pieces.push(current);

    return pieces;
}

// Puts the atoms into lines that fit maxWidth.   Returns [{ atoms, width }]
function wrapAtoms(ctx, atoms, fontSize, maxWidth) {
    ctx.font = `${fontSize}px ${TEXT_FONT}`;

    const lines = [];
    let line = { atoms: [], width: 0 };

    const pushLine = () => {
        while (line.atoms.length && line.atoms[line.atoms.length - 1].type === 'space') {
            line.width -= measureAtom(ctx, line.atoms.pop(), fontSize);
        }
        lines.push(line);
        line = { atoms: [], width: 0 };
    };

    for (const atom of atoms) {
        if (atom.type === 'newline') {
            pushLine();
            continue;
        }

        if (atom.type === 'space' && line.atoms.length === 0) continue;

        if (atom.type === 'word' && measureAtom(ctx, atom, fontSize) > maxWidth) {
            for (const piece of splitLongWord(ctx, atom.value, maxWidth)) {
                const pieceAtom = { type: 'word', value: piece };
                const pieceWidth = measureAtom(ctx, pieceAtom, fontSize);

                if (line.atoms.length && line.width + pieceWidth > maxWidth) pushLine();

                line.atoms.push(pieceAtom);
                line.width += pieceWidth;
            }
            continue;
        }

        const width = measureAtom(ctx, atom, fontSize);

        if (line.atoms.length && line.width + width > maxWidth) {
            pushLine();
            if (atom.type === 'space') continue;
        }

        line.atoms.push(atom);
        line.width += width;
    }

    pushLine();

    return lines;
}

function drawLine(ctx, line, centerX, baselineY, fontSize, font, color) {
    ctx.font = `${fontSize}px ${font}`;
    ctx.fillStyle = color;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';

    let x = centerX - line.width / 2;

    for (const atom of line.atoms) {
        const width = measureAtom(ctx, atom, fontSize);

        if (atom.type === 'emoji' && atom.image) {
            const size = fontSize * 1.08;
            ctx.drawImage(atom.image, x, baselineY - size * 0.84, size, size);
        } else if (atom.type === 'word') {
            ctx.fillText(atom.value, x, baselineY);
        }

        x += width;
    }
}

function roundedRect(ctx, x, y, width, height, radius) {
    ctx.beginPath();
    ctx.moveTo(x + radius, y);
    ctx.arcTo(x + width, y, x + width, y + height, radius);
    ctx.arcTo(x + width, y + height, x, y + height, radius);
    ctx.arcTo(x, y + height, x, y, radius);
    ctx.arcTo(x, y, x + width, y, radius);
    ctx.closePath();
}

function drawAvatar(ctx, image) {
    ctx.save();
    ctx.beginPath();
    ctx.rect(0, 0, AVATAR_WIDTH, HEIGHT);
    ctx.clip();

    if (image) {
        // "cover" fit: fill the whole left area and cut off what does not fit
        const scale = Math.max(AVATAR_WIDTH / image.width, HEIGHT / image.height);
        const drawWidth = image.width * scale;
        const drawHeight = image.height * scale;

        ctx.drawImage(
            image,
            (AVATAR_WIDTH - drawWidth) / 2,
            (HEIGHT - drawHeight) / 2,
            drawWidth,
            drawHeight,
        );
    } else {
        ctx.fillStyle = '#1e1f22';
        ctx.fillRect(0, 0, AVATAR_WIDTH, HEIGHT);
    }

    // Fade the avatar into the black background
    const fade = ctx.createLinearGradient(AVATAR_WIDTH * AVATAR_FADE_START, 0, AVATAR_WIDTH, 0);
    fade.addColorStop(0, 'rgba(0,0,0,0)');
    fade.addColorStop(1, 'rgba(0,0,0,1)');
    ctx.fillStyle = fade;
    ctx.fillRect(0, 0, AVATAR_WIDTH, HEIGHT);

    ctx.restore();
}

// "- Name" on one line. Gets smaller if the name is long.
async function buildNameLine(ctx, name, maxWidth) {
    const atoms = await loadEmojis(tokenize(`- ${name}`));

    for (let size = NAME_FONT_SIZE; size >= 16; size -= 2) {
        ctx.font = `${size}px ${NAME_FONT}`;
        const width = atoms.reduce((sum, atom) => sum + measureAtom(ctx, atom, size), 0);

        if (width <= maxWidth || size === 16) {
            // Still too long at the smallest size: cut the end and add "…"
            if (width > maxWidth) {
                while (atoms.length > 3 && atoms.reduce((sum, atom) => sum + measureAtom(ctx, atom, size), 0) > maxWidth) {
                    atoms.pop();
                }
                atoms.push({ type: 'word', value: '…' });
            }

            const finalWidth = atoms.reduce((sum, atom) => sum + measureAtom(ctx, atom, size), 0);

            return { size, line: { atoms, width: finalWidth } };
        }
    }

    return null;
}

/**
 * Makes the quote picture.
 * @param {object} options
 * @param {string} options.text        the quote
 * @param {string} options.name        name shown under the quote
 * @param {string} options.handle      username shown small at the bottom (without @)
 * @param {string} options.avatarUrl   avatar picture link (png / jpg / webp)
 * @returns {Promise<Buffer>} PNG file
 */
async function renderQuoteImage({ text, name, handle, avatarUrl }) {
    let quote = normalizeFancyLetters(String(text ?? '')).replace(/\r/g, '').trim();

    if ([...quote].length > MAX_QUOTE_CHARS) {
        quote = `${[...quote].slice(0, MAX_QUOTE_CHARS).join('').trimEnd()}…`;
    }

    const displayName = normalizeFancyLetters(String(name ?? 'Unknown'));
    const [avatar, atoms] = await Promise.all([
        avatarUrl ? fetchImage(avatarUrl) : null,
        loadEmojis(tokenize(quote)),
    ]);

    const canvas = createCanvas(WIDTH, HEIGHT);
    const ctx = canvas.getContext('2d');

    // Black rounded background
    roundedRect(ctx, 0, 0, WIDTH, HEIGHT, CORNER_RADIUS);
    ctx.clip();
    ctx.fillStyle = '#000000';
    ctx.fillRect(0, 0, WIDTH, HEIGHT);

    drawAvatar(ctx, avatar);

    // ----- text side -----
    const textAreaWidth = WIDTH - AVATAR_WIDTH;
    const centerX = AVATAR_WIDTH + textAreaWidth / 2;
    const maxTextWidth = textAreaWidth - TEXT_PADDING * 2;

    const nameBlock = await buildNameLine(ctx, displayName, maxTextWidth);
    const nameHeight = nameBlock.size * LINE_HEIGHT;
    const handleHeight = HANDLE_FONT_SIZE * LINE_HEIGHT;
    const gap = 20;
    const maxBlockHeight = HEIGHT - 110;

    // Biggest text size that still fits
    let fontSize = QUOTE_FONT_MAX;
    let lines = wrapAtoms(ctx, atoms, fontSize, maxTextWidth);

    while (fontSize > QUOTE_FONT_MIN) {
        const height = lines.length * fontSize * LINE_HEIGHT + gap + nameHeight + handleHeight;
        if (height <= maxBlockHeight) break;

        fontSize -= 2;
        lines = wrapAtoms(ctx, atoms, fontSize, maxTextWidth);
    }

    // Still too tall at the smallest size: drop the extra lines
    const maxLines = Math.max(1, Math.floor((maxBlockHeight - gap - nameHeight - handleHeight) / (fontSize * LINE_HEIGHT)));

    if (lines.length > maxLines) {
        lines = lines.slice(0, maxLines);
        const last = lines[maxLines - 1];
        last.atoms.push({ type: 'word', value: '…' });
        ctx.font = `${fontSize}px ${TEXT_FONT}`;
        last.width += ctx.measureText('…').width;
    }

    const quoteHeight = lines.length * fontSize * LINE_HEIGHT;
    const blockHeight = quoteHeight + gap + nameHeight + handleHeight;
    let y = (HEIGHT - blockHeight) / 2;

    for (const line of lines) {
        // baseline sits about 78% down the line box
        drawLine(ctx, line, centerX, y + fontSize * LINE_HEIGHT * 0.78, fontSize, TEXT_FONT, '#ffffff');
        y += fontSize * LINE_HEIGHT;
    }

    y += gap;
    drawLine(ctx, nameBlock.line, centerX, y + nameHeight * 0.78, nameBlock.size, NAME_FONT, 'rgba(255,255,255,0.95)');
    y += nameHeight;

    if (handle) {
        ctx.font = `${HANDLE_FONT_SIZE}px ${HANDLE_FONT}`;
        ctx.fillStyle = 'rgba(255,255,255,0.32)';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'alphabetic';
        ctx.fillText(`@${handle}`, centerX, y + handleHeight * 0.7);
    }

    return canvas.toBuffer('image/png');
}
